import * as T from 'three';
// Reference interaction system, bound to the four lamps in the verified native furniture.
export function createBedsideLighting(scene,{canvas,onChange,isWalk,refined}){
 const root=new T.Group();root.name='Independent bedside lighting';scene.add(root);let bindings=[];const levels={guest:75,loft:75},states={'guest-side-a':true,'guest-side-b':true,'loft-side-a':true,'loft-side-b':true};let kelvin=2700,owned=[],restorations=[];
 const $=s=>document.querySelector(s);function color(k){const t=k/100;return new T.Color().setRGB(T.MathUtils.clamp(255,0,255)/255,T.MathUtils.clamp(99.4708025861*Math.log(t)-161.1195681661,0,255)/255,T.MathUtils.clamp(t<=19?0:138.5177312231*Math.log(t-10)-305.0447927307,0,255)/255,T.SRGBColorSpace);}
 function sync(){const c=color(kelvin);for(const b of bindings){const power=states[b.id]?levels[b.room]/100:0;b.light.intensity=12*power;b.fill.intensity=.9*power;b.light.color.copy(c);b.fill.color.copy(c);b.shades.forEach(m=>{m.emissive.copy(c);m.emissiveIntensity=power*.35;});b.bulbs.forEach(m=>{m.emissive.copy(c);m.emissiveIntensity=power*2.2;});const button=$(`[data-bedside-lamp="${b.id}"]`);button.setAttribute('aria-pressed',String(states[b.id]));button.textContent=(b.id.endsWith('a')?'Left':'Right')+(states[b.id]?' · On':' · Off');}
  for(const room of ['guest','loft']){$('#bedside-'+room).checked=Object.entries(states).some(([id,on])=>id.startsWith(room)&&on);$('#bedside-value-'+room).value=levels[room]+'%';$('#bedside-level-'+room).value=levels[room];}$('#bedside-warmth-value').value=kelvin+' K';$('#bedside-warmth').value=kelvin;canvas.dataset.bedside=JSON.stringify({levels,kelvin,states});onChange();}
 function unbind(){for(const r of restorations)r.mesh.material=r.material;restorations=[];for(const m of owned)m.dispose();owned=[];for(const b of bindings){root.remove(b.light,b.light.target,b.fill);}bindings=[];}
 function bind(interior){unbind();for(const id of Object.keys(states)){const node=interior.movable.find(n=>n.userData.itemId===id);if(!node)continue;const room=id.startsWith('guest')?'guest':'loft',shades=[],bulbs=[],hits=[];node.traverse(o=>{if(!o.isMesh)return;let list=Array.isArray(o.material)?o.material:[o.material];if(list.some(m=>m.name==='MT | linen'||m.name==='MT | light'))restorations.push({mesh:o,material:o.material});o.material=list.map(m=>{if(m.name==='MT | linen'||m.name==='MT | light'){const clone=m.clone();owned.push(clone);(m.name==='MT | linen'?shades:bulbs).push(clone);o.userData.bedsideLamp=id;hits.push(o);return clone;}return m;});if(o.material.length===1)o.material=o.material[0];});const light=new T.SpotLight('#ffd6a2',12,3.2,1.05,.85,2);light.castShadow=refined();light.shadow.mapSize.set(512,512);light.shadow.bias=-.0002;light.shadow.normalBias=.008;light.shadow.radius=4;const fill=new T.PointLight('#ffd6a2',.9,1.5,2);root.add(light,light.target,fill);bindings.push({id,room,node,shades,bulbs,hits,light,fill,last:new T.Vector3(Infinity,Infinity,Infinity)});}update();sync();}
 function update(){for(const b of bindings){const shadow=refined();if(b.light.castShadow!==shadow){b.light.castShadow=shadow;if(!shadow&&b.light.shadow.map){b.light.shadow.map.dispose();b.light.shadow.map=null;}}const p=b.node.getWorldPosition(new T.Vector3());if(p.distanceToSquared(b.last)<.000001)continue;b.last.copy(p);b.light.position.copy(p).add(new T.Vector3(0,.90,0));b.fill.position.copy(b.light.position);b.light.target.position.copy(p).add(new T.Vector3(b.room==='guest'?.4:-.4,.43,0));onChange();}}
 function toggle(id){states[id]=!states[id];sync();}
 for(const room of ['guest','loft']){$('#bedside-'+room).onchange=e=>{for(const id in states)if(id.startsWith(room))states[id]=e.target.checked;sync();};$('#bedside-level-'+room).oninput=e=>{levels[room]=Number(e.target.value);sync();};}
 document.querySelectorAll('[data-bedside-lamp]').forEach(b=>b.onclick=()=>toggle(b.dataset.bedsideLamp));$('#bedside-warmth').oninput=e=>{kelvin=Number(e.target.value);sync();};document.querySelectorAll('[data-bedside-preset]').forEach(b=>b.onclick=()=>{const [level,k]={reading:[100,3000],relax:[55,2500],sleep:[10,2200]}[b.dataset.bedsidePreset];levels.guest=levels.loft=level;kelvin=k;for(const id in states)states[id]=true;document.querySelectorAll('[data-bedside-preset]').forEach(x=>x.classList.toggle('selected',x===b));sync();});
 let down;canvas.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);canvas.addEventListener('click',e=>{if(!isWalk()||!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return;const camera=isWalk(),ray=new T.Raycaster(),p=new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(p,camera);const hit=ray.intersectObjects(bindings.flatMap(b=>b.hits),false).find(h=>h.distance<3.2);if(hit)toggle(hit.object.userData.bedsideLamp);});
 return{bind,unbind,update,sync,setClipping(planes){root.traverse(o=>{if(o.isMesh)o.material.clippingPlanes=planes;});}};
}
